/**
     * This method check if the indices that were created with a previous lucene version, meaning that they need to be reindexed
     * in order to be writable in the _next_ lucene version. It excludes searchable snapshots as they are not writable.
     *
     * @param indexMetadata the index metadata
     * @param filterToBlockedStatus if true, only indices that are write blocked will be returned,
     *                              if false, only those without a block are returned
     * @return a predicate that returns true for indices that need to be reindexed
     */
    public static boolean reindexRequired(IndexMetadata indexMetadata, boolean filterToBlockedStatus) {
        return creationVersionBeforeMinimumWritableVersion(indexMetadata)
            && isNotSystem(indexMetadata)
            && isNotSearchableSnapshot(indexMetadata)
            && matchBlockedStatus(indexMetadata, filterToBlockedStatus);
    }

private void migrateDataStream(
        SystemDataStreamMigrationInfo migrationInfo,
        ClusterState clusterState,
        Consumer<SystemDataStreamMigrationInfo> listener
    ) {
        String dataStreamName = migrationInfo.getDataStreamName();
        logger.info(
            "migrating indices from data stream [{}] from feature [{}] to new indices",
            dataStreamName,
            migrationInfo.getFeatureName()
        );

        ReindexDataStreamAction.ReindexDataStreamRequest reindexRequest = new ReindexDataStreamAction.ReindexDataStreamRequest(
            ReindexDataStreamAction.Mode.UPGRADE,
            dataStreamName
        );

        ActionListener<ActionResponse> innerListener = ActionListener.wrap(response -> listener.accept(migrationInfo), this::markAsFailed);

        try {
            migrationInfo.createClient(baseClient)
                .execute(
                    ReindexDataStreamAction.INSTANCE,
                    reindexRequest,
                    innerListener.delegateFailureAndWrap((delegate, startMigrationResponse) -> {
                        if (startMigrationResponse.isAcknowledged() == false) {
                            logger.error("failed to migrate indices from data stream [{}]", dataStreamName);
                            delegate.onFailure(
                                new ElasticsearchException(
                                    "reindex system data stream ["
                                        + dataStreamName
                                        + "] from feature ["
                                        + migrationInfo.getFeatureName()
                                        + "] response is not acknowledge"
                                )
                            );
                        }

                        checkDataStreamMigrationStatus(migrationInfo, delegate);
                    })
                );
        } catch (Exception ex) {
            logger.error(
                () -> format(
                    "error occurred while migrating old indices data stream [%s] from feature [%s] to new indices",
                    dataStreamName,
                    migrationInfo.getFeatureName()
                ),
                ex
            );
            innerListener.onFailure(ex);
        }
    }

